import forgelib as F
G = F.make(slug="the-forge-goblin-cave", order=9, kw="unlock the goblin cave",
 title="How to Unlock the Goblin Cave in The Forge (Quest Guide)",
 h1="How to Unlock the Goblin Cave in The Forge: Every Goblin King Quest",
 desc="How to unlock the Goblin Cave in The Forge: every Goblin King quest and its gold and ore cost, where the cave is, the crystal ores inside, and if it's worth it.",
 kw2=["the forge goblin cave","the forge goblin king quest","how to unlock goblin cave the forge","the forge crystal ores","the forge goblin village"],
 related=["the-forge-goblin-lord-quest","the-forge-galaxite","the-forge-volcanic-depths","the-forge-bard-quest"],
 ids=["DvczuG8-rXA"],
 lead="The <strong>Goblin Cave</strong> is a crystal cave on the Forgotten Kingdom, locked behind the Goblin King's questline. Fridge's full tutorial shows the route. Here's how to unlock the Goblin Cave: every quest step, what it costs, and what's inside, as listed on the Forge Wiki on November 11, 2026.",
 heading="Watch Fridge's Goblin Cave Tutorial",
 sections=[
 ("where","Where the Goblin King Is","""<p>From the Forgotten Kingdom spawn, don't take the path up to the Ruined Cave. Keep going <strong>down</strong> the path until you see two goblins guarding the <strong>Goblin Village</strong>. The Goblin King lives there. Pro Game Guides notes that the guards won't let <strong>Zombie</strong>-race players in, but any other race can enter.</p>"""),
 ("quests","Every Goblin King Quest","""<div class="table-wrap"><table><caption>Goblin King questline (Forge Wiki)</caption><thead><tr><th scope="col">Quest</th><th scope="col">Bring</th><th scope="col">Reward (XP)</th></tr></thead><tbody>
<tr><td>Goblin King 1</td><td>5,000 Gold</td><td>1,000</td></tr>
<tr><td>Goblin King 2</td><td>3 Topaz + 10,000 Gold</td><td>1,500</td></tr>
<tr><td>Goblin King 3</td><td>5 Diamond + 15,000 Gold</td><td>2,500</td></tr>
<tr><td>Goblin King 4</td><td>5 Emerald + 20,000 Gold</td><td>4,500</td></tr>
<tr><td>Let's get over it!</td><td>Final payment</td><td>7,500</td></tr></tbody></table></div>
<p>That's 50,000 Gold across the first four quests. Allthings.how puts the total for the whole questline at <strong>85,000 Gold</strong>, including the final step. When you finish, the Goblin King gives you the key to the Goblin Cave.</p>"""),
 ("unlock","How to Unlock the Cave","""<p>To unlock the Goblin Cave once you've saved up:</p>
<ol class="steps"><li>Mine Topaz, Diamond and Emerald in the Ruined Cave while you save Gold.</li><li>Hand in each Goblin King quest in order.</li><li>Collect the <strong>Goblin Cave key</strong> after the last payment.</li><li>Use it on the cave entrance to the right of the Goblin King.</li></ol>"""),
 ("inside","What's Inside the Goblin Cave","""<p>The Forge Wiki describes it as a dangerous cavern full of slimes and rare crystals. Its crystal ores include Blue, Crimson, Green, Magenta and Orange Crystal Ore (Epic), Rainbow Crystal (Legendary) and Arcane Crystal (Mythic). Arcane Crystal is a key crafting ingredient for Heavenite and Stolen Heart. Bring a strong pickaxe: Pro Game Guides suggests Mythril, Lightite, Magma, Arcane or Demonic.</p>
<p>When Fridge made his video in December 2025, Galaxite could also drop here at 1 in 1,000,000. It's now crafted in the Void Cave instead. See our <a href="the-forge-galaxite.html">Galaxite guide</a>.</p>"""),
 ("worth","Is the Goblin Cave Worth It?","""<p>Not early on. The Forge Wiki's quest priority list rates the Goblin King quest <strong>low priority</strong>, and Pro Game Guides says to buy better pickaxes first. Do it once you have spare Gold and want crystal ores for crafting. Island 3 has a sequel questline from the Goblin Lord. See the <a href="the-forge-goblin-lord-quest.html">Goblin Lord quest guide</a>.</p>""")],
 faq=[("How do you unlock the Goblin Cave in The Forge?","Complete the Goblin King's questline in the Forgotten Kingdom's Goblin Village, then use the key he gives you on the cave entrance."),
      ("How much does the Goblin Cave cost?","At least 50,000 Gold plus 3 Topaz, 5 Diamond and 5 Emerald across the first four quests. Allthings.how puts the full questline at 85,000 Gold."),
      ("Can Zombies enter the Goblin Village?","No. Pro Game Guides reports that the goblin guards turn away Zombie-race players.")],
 sources=[F.wiki("Goblin_King%27s_Questline","Goblin King's Questline"),F.wiki("Goblin_King_1","Goblin King 1–4 quests"),F.wiki("Forgotten_Kingdom","Forgotten Kingdom"),F.wiki("Guide","Community guide: quest priority"),("Allthings.how: Galaxite and the Goblin Cave","https://allthings.how/galaxite-in-the-forge-how-the-1-in-a-million-ore-actually-works/"),("Pro Game Guides: Forgotten Kingdom map","https://progameguides.com/roblox/the-forge-map-all-islands-locations-level-requirements/")],
 howto=("How to unlock the Goblin Cave in The Forge",[("Find the Goblin King","Follow the lower path on the Forgotten Kingdom to the Goblin Village.","where"),("Pay the quests","Bring the Gold and ores for each Goblin King quest in order.","quests"),("Get the key","Collect the Goblin Cave key after the final quest.","unlock"),("Enter the cave","Use the key on the entrance beside the Goblin King.","unlock")]))
